CREATE SET TABLE MDP01_META.META_SOURCE_SYSTEM ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      SOURCE_SYSTEM_ID INTEGER NOT NULL,      SOURCE_SYSTEM_NAME VARCHAR(128) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      SOURCE_SYSTEM_CODE VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      SOURCE_TYPE VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      HOST_NAME VARCHAR(255) CHARACTER SET LATIN NOT CASESPECIFIC,      PORT_NUMBER INTEGER,      DEFAULT_DATABASE VARCHAR(128) CHARACTER SET LATIN NOT CASESPECIFIC,      DEFAULT_SCHEMA VARCHAR(128) CHARACTER SET LATIN NOT CASESPECIFIC,      ODBC_DSN_NAME VARCHAR(128) CHARACTER SET LATIN NOT CASESPECIFIC,      CREDENTIAL_USER_WALLET VARCHAR(128) CHARACTER SET LATIN NOT CASESPECIFIC,      CREDENTIAL_PASSWORD_WALLET VARCHAR(128) CHARACTER SET LATIN NOT CASESPECIFIC,      IS_ACTIVE CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT 'Y',      BESCHREIBUNG VARCHAR(2000) CHARACTER SET LATIN NOT CASESPECIFIC,      VERANTWORTLICHER VARCHAR(200) CHARACTER SET LATIN NOT CASESPECIFIC,      KONTAKT_EMAIL VARCHAR(200) CHARACTER SET LATIN NOT CASESPECIFIC,      CREATED_BY VARCHAR(200) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT USER ,      CREATE_TIMESTAMP TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),      MODIFIED_BY VARCHAR(200) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT USER ,      LAST_ALTER_TIMESTAMP TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6))PRIMARY INDEX ( SOURCE_SYSTEM_ID );